unknown=[(5,15),(5,16),(15,5),(16,5),(19,19),(19,20),(20,19),(20,20)]
# Match surrounding neighborhoods of each unknown cell with known cells; count candidate values for each radius.
for p in unknown:
 i,j=p
 print('\n',p)
 for rad in [1,2,3,4,5]:
  scores={}
  matches=[]
  for a in range(30):
   for b in range(30):
    if (a,b)==p or g[a][b]==6 or abs(a-i)<=1 and abs(b-j)<=1: continue
    comp=tot=0
    for di in range(-rad,rad+1):
     for dj in range(-rad,rad+1):
      x,y=i+di,j+dj; u,v=a+di,b+dj
      if 0<=x<30 and 0<=y<30 and 0<=u<30 and 0<=v<30 and (di,dj)!=(0,0) and g[x][y]!=6 and g[u][v]!=6:
       tot+=1; comp += (g[x][y]==g[u][v])
    if tot>=5 and comp/tot>=.85:
     scores[g[a][b]]=scores.get(g[a][b],0)+comp/tot
     matches.append((comp/tot,tot,(a,b),g[a][b]))
  print(rad,sorted(scores.items(),key=lambda x:-x[1])[:5], 'topmatch', sorted(matches,reverse=True)[:2])

